import "core-js/modules/web.dom.iterable";
export default {
  name: '',
  components: {
    // TsFormRadio: resolve => require(['@/resources/plugins/TsForm/TsFormRadio'], resolve)
  },
  props: {
    attrData: {
      type: Object
    },
    valueList: {
      type: Array
    }
  },
  data: function data() {
    return {
      currentValue: ''
    };
  },
  beforeCreate: function beforeCreate() {},
  created: function created() {},
  beforeMount: function beforeMount() {},
  mounted: function mounted() {},
  beforeUpdate: function beforeUpdate() {},
  updated: function updated() {},
  activated: function activated() {},
  deactivated: function deactivated() {},
  beforeDestroy: function beforeDestroy() {},
  destroyed: function destroyed() {},
  methods: {
    getData: function getData() {
      if (this.valueList && this.valueList.length > 0) {
        this.currentValue = this.valueList[0];
      } else {
        this.currentValue = '';
      }
    },
    clickRadio: function clickRadio(currentValue) {
      // console.log(111, currentValue)
      if (this.currentValue == currentValue) {
        this.currentValue = null;
      } else {
        this.currentValue = currentValue;
      }
      this.setData(this.currentValue);
    },
    setData: function setData(val) {
      this.$emit('setData', [val]);
      // this.$emit('setValue', [val]);
    },
    valid: function valid() {
      //验证数据合法性
      var handler = this.$refs['handler'];
      return handler.valid();
    }
  },
  filter: {},
  computed: {
    dataList: function dataList() {
      var dataList = [];
      if (this.attrData.config && this.attrData.config.members) {
        this.attrData.config.members.forEach(function (element) {
          if (element && element.trim()) {
            dataList.push({
              text: element.trim(),
              value: element.trim()
            });
          }
        });
      }
      return dataList;
    },
    value: function value() {
      if (this.valueList && this.valueList.length > 0) {
        return this.valueList[0];
      }
      return '';
    }
  },
  watch: {
    valueList: {
      handler: function handler(newValue, oldValue) {
        this.getData();
      },
      deep: true,
      immediate: true
    }
  }
};
